package com.campus.student.application;
import java.time.Clock; import java.util.*; import com.campus.organization.application.OrganizationUnitManagementService; import com.campus.organization.domain.OrganizationUnitStatus; import com.campus.student.domain.*; import org.springframework.dao.DataIntegrityViolationException; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional;
@Service public class StudentManagementService { private final StudentRepository students; private final OrganizationUnitManagementService organizations; private final Clock clock; public StudentManagementService(StudentRepository s,OrganizationUnitManagementService o,Clock c){students=s;organizations=o;clock=c;} @Transactional public Student create(String number,String name,String email,UUID unit,StudentStatus status){validateUnit(unit); Student s;try{s=Student.create(UUID.randomUUID(),number,name,email,unit,status==null?StudentStatus.ACTIVE:status,clock.instant());}catch(Student.InvalidStudentException e){throw new RequestValidationException();}if(students.existsByStudentNumber(s.studentNumber()))throw new StudentNumberAlreadyExistsException();try{return students.save(s);}catch(DataIntegrityViolationException e){throw new StudentNumberAlreadyExistsException();}} @Transactional(readOnly=true) public Student get(UUID id){return students.findById(id).orElseThrow(StudentNotFoundException::new);} @Transactional(readOnly=true) public List<Student> list(){return students.findAll();} @Transactional public Student update(UUID id,String n,String name,String email,UUID unit,StudentStatus status,long version){Student old=get(id);validateUnit(unit);Student next;try{next=new Student(id,n,name,email,unit,status,old.rowVersion(),old.createdAt(),clock.instant());}catch(Student.InvalidStudentException e){throw new RequestValidationException();}try{return students.saveMutation(next,version);}catch(NoSuchElementException e){throw new StudentNotFoundException();}catch(DataIntegrityViolationException e){throw new StudentNumberAlreadyExistsException();}} private void validateUnit(UUID id){try{if(organizations.get(id).status()!=OrganizationUnitStatus.ACTIVE)throw new OrganizationUnitUnavailableException();}catch(OrganizationUnitManagementService.OrganizationUnitNotFoundException e){throw new OrganizationUnitUnavailableException();}} public static final class StudentNotFoundException extends RuntimeException{} public static final class StudentNumberAlreadyExistsException extends RuntimeException{} public static final class ConcurrentStudentModificationException extends RuntimeException{} public static final class OrganizationUnitUnavailableException extends RuntimeException{} public static final class RequestValidationException extends RuntimeException{} }
